				 * is now parent's parent in the path */
				sib->color = BLACK;
				parent->color = RED;
				rotate_left(t, pp, parent);
				path[d - 1] = sib;
				path[d]     = parent;
				d++;
				pp  = sib;
				sib = parent->right;
